def parse_tutar(metin):
    """Tutar metnini float'a çevirir. Başarısızsa None döner."""
    if isinstance(metin, (int, float)) and not isinstance(metin, bool):
        return metin

    if not isinstance(metin, str):
        return None

    s = metin.strip()
    if not s:
        return None

    # ₺, TL ve boşlukları at
    s = re.sub(r'[₺\s]', '', s).strip()
    s = s.upper().replace('TL', '').strip()

    if not s:
