            # Noktadan sonra tam 3 rakam varsa -> binlik ayırıcı
            if re.fullmatch(r'\d{3}', nokta_sonra[1]):
                s = s.replace('.', '')
                try:
                    return float(s)
                except ValueError:
                    return None
            else:
                # Ondalık ayırıcı
                try:
                    return float(s.replace('.', ''))
                except ValueError:
                    return None
    else:
        # Sadece rakam
        try:
            return float(s)
